from pathlib import Path
import os,json,subprocess,pwd
old=Path('/home/ubuntu/.local/share/rea-chatgpt-trial')
new=Path('/srv/projects/Engenheira-reversa')
def run(args,secs=15):
 return subprocess.run(args,capture_output=True,text=True,timeout=secs)
def state(name):
 return run(['systemctl','is-active',name+'.service'],8).stdout.strip()
def botstate():
 r=run(['pm2','jlist'],14)
 if r.returncode:raise RuntimeError('PM2 state unavailable')
 return {a.get('name'):(a.get('pm2_env') or {}).get('status') for a in json.loads(r.stdout) if a.get('name') in ('iptvpn_bot','telegram-robot-leads')}
protected=['fadego-staging','lowcost-europa','pink-iptv-backend','pink-vpn','pm2-root','nginx','postgresql@16-main']
baseline={n:state(n) for n in protected}
if any(v!='active' for v in baseline.values()):raise RuntimeError('Protected service unavailable')
if any(botstate().get(n)!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Bot offline')
if not old.is_dir() or old.is_symlink() or new.exists() or new.is_symlink() or old.stat().st_dev!=new.parent.stat().st_dev:
 raise RuntimeError('Old/new REA project location mismatch')
owner=pwd.getpwuid(old.stat().st_uid).pw_name
repo=old/'repository'
if owner!='ubuntu' or not (repo/'.git').is_dir():raise RuntimeError('Ownership or repository mismatch')
def git(path,*args):
 return run(['sudo','-n','-u','ubuntu','git','-C',str(path),*args],16)
origin=git(repo,'remote','get-url','origin')
if origin.returncode or 'martaxi-boss/Engenheira-reversa' not in origin.stdout:
 raise RuntimeError('REA Trial GitHub origin is not the expected project')
before=git(repo,'status','--porcelain','--untracked-files=no')
if before.returncode:raise RuntimeError('Project Git status unavailable')
oldinode=old.stat().st_ino
volume=run(['du','-x','-s','-B1',str(old)],58)
if volume.returncode:raise RuntimeError('Cannot measure project')
sz=int(volume.stdout.split()[0])
for proc in Path('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:
  cwd=os.readlink(proc/'cwd')
  if cwd==str(old) or cwd.startswith(str(old)+'/'):raise RuntimeError('Project used as current working directory: '+proc.name)
 except OSError:pass
print('REA_TRIAL_PREMOVE_BYTES='+str(sz))
moved=False
try:
 old.rename(new);moved=True
 old.symlink_to(new,target_is_directory=True)
 if not old.is_symlink() or old.resolve()!=new or new.stat().st_ino!=oldinode:raise RuntimeError('Project root symlink or inode mismatch')
 new_repo=new/'repository'
 after=git(new_repo,'status','--porcelain','--untracked-files=no')
 if after.returncode or after.stdout!=before.stdout:raise RuntimeError('Git status changed on canonical path')
 rem=git(new_repo,'remote','get-url','origin')
 if rem.returncode or rem.stdout!=origin.stdout:raise RuntimeError('Git repo no longer associated with origin')
 new_size=run(['du','-x','-s','-B1',str(new)],58)
 if new_size.returncode or int(new_size.stdout.split()[0])!=sz:raise RuntimeError('Unexpected project size')
 for name,v in baseline.items():
  if state(name)!=v:raise RuntimeError('Service state changed: '+name)
 if any(botstate().get(n)!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Telegram bot state changed')
except Exception:
 if old.is_symlink() and old.resolve()==new:old.unlink()
 if moved and new.exists() and not old.exists():new.rename(old)
 print('REA_TRIAL_ROOT_ROLLBACK=APPLIED')
 raise
print('REA_TRIAL_CANONICAL_ROOT='+str(new))
print('REA_TRIAL_PREVIOUS_PATH_SYMLINK='+str(old))
print('REA_TRIAL_GITHUB_REPO_MATCH=PASS')
print('REA_TRIAL_GIT_TRACKED_FILES_PRESERVED=YES')
print('REA_TRIAL_FILES_BYTES='+str(sz))
print('OTHER_PROJECTS_AND_SERVICES=UNCHANGED')
print('REA_TRIAL_DISK_GAIN_BYTES=0')
print('REA_TRIAL_CANONICAL_MOVE=PASS')
